7	/**
8	 * @fileoverview Automation overlay utilities for visual indication during browser automation.
9	 *
10	 * Provides functions to inject and remove a pulsating blue border overlay
11	 * that indicates when the browser is under AI agent control.
12	 *
13	 * Uses the Web Animations API instead of injected <style> tags so the
14	 * animation works on sites with strict Content Security Policies (e.g. google.com).
15	 *
16	 * The script strings are passed to chrome-devtools-mcp's evaluate_script tool
17	 * which expects a plain function expression (NOT an IIFE).
18	 */
19	
20	import type { BrowserManager } from './browserManager.js';
21	import { debugLogger } from '../../utils/debugLogger.js';
22	
23	const OVERLAY_ELEMENT_ID = '__gemini_automation_overlay';
24	
25	/**
26	 * Builds the JavaScript function string that injects the automation overlay.
27	 *
28	 * Returns a plain arrow-function expression (no trailing invocation) because
29	 * chrome-devtools-mcp's evaluate_script tool invokes it internally.
30	 *
31	 * Avoids nested template literals by using string concatenation for cssText.
32	 */
33	function buildInjectionScript(): string {
34	  return `() => {
35	    const id = '${OVERLAY_ELEMENT_ID}';
36	    const existing = document.getElementById(id);
37	    if (existing) existing.remove();
38	
39	    const overlay = document.createElement('div');
40	    overlay.id = id;
41	    overlay.setAttribute('aria-hidden', 'true');
42	    overlay.setAttribute('role', 'presentation');
43	
44	    Object.assign(overlay.style, {
45	      position: 'fixed',
46	      top: '0',
47	      left: '0',
48	      right: '0',
49	      bottom: '0',
50	      zIndex: '2147483647',
51	      pointerEvents: 'none',
52	      border: '6px solid rgba(66, 133, 244, 1.0)',
53	    });
54	
55	    document.documentElement.appendChild(overlay);
56	
57	    try {
58	      overlay.animate([
59	        { borderColor: 'rgba(66,133,244,0.3)', boxShadow: 'inset 0 0 8px rgba(66,133,244,0.15)' },
60	        { borderColor: 'rgba(66,133,244,1.0)', boxShadow: 'inset 0 0 16px rgba(66,133,244,0.5)' },
61	        { borderColor: 'rgba(66,133,244,0.3)', boxShadow: 'inset 0 0 8px rgba(66,133,244,0.15)' }
62	      ], { duration: 2000, iterations: Infinity, easing: 'ease-in-out' });
63	    } catch (e) {
64	      // Silently ignore animation errors, as they can happen on sites with strict CSP.
65	      // The border itself is the most important visual indicator.
66	    }
67	
68	    return 'overlay-injected';
69	  }`;
70	}
71	
72	/**
73	 * Builds the JavaScript function string that removes the automation overlay.
74	 */
75	function buildRemovalScript(): string {
76	  return `() => {
77	    const el = document.getElementById('${OVERLAY_ELEMENT_ID}');
78	    if (el) el.remove();
79	    return 'overlay-removed';
80	  }`;
81	}
82	
83	/**
84	 * Injects the automation overlay into the current page.
85	 */
86	export async function injectAutomationOverlay(
87	  browserManager: BrowserManager,
88	  signal?: AbortSignal,
89	): Promise<void> {
90	  try {
91	    debugLogger.log('Injecting automation overlay...');
92	
93	    const result = await browserManager.callTool(
94	      'evaluate_script',
95	      { function: buildInjectionScript() },
96	      signal,
97	    );
98	
99	    if (result.isError) {
100	      debugLogger.warn('Failed to inject automation overlay:', result);
101	    } else {
102	      debugLogger.log('Automation overlay injected successfully');
103	    }
104	  } catch (error) {
105	    debugLogger.warn('Error injecting automation overlay:', error);
106	  }
107	}
108	
109	/**
110	 * Removes the automation overlay from the current page.
111	 */
112	export async function removeAutomationOverlay(
113	  browserManager: BrowserManager,
114	  signal?: AbortSignal,
115	): Promise<void> {
116	  try {
117	    debugLogger.log('Removing automation overlay...');
118	
119	    const result = await browserManager.callTool(
120	      'evaluate_script',
121	      { function: buildRemovalScript() },
122	      signal,
123	    );
124	
125	    if (result.isError) {
126	      debugLogger.warn('Failed to remove automation overlay:', result);
127	    } else {
128	      debugLogger.log('Automation overlay removed successfully');
129	    }
130	  } catch (error) {
131	    debugLogger.warn('Error removing automation overlay:', error);
132	  }
133	}
