/**
 * @fileoverview Input-blocking overlay utilities for browser automation.
 *
 * Provides functions to inject and remove a full-viewport overlay that
 * captures pointer/keyboard input, preventing the human from interfering
 * with the browser while the agent is performing an interactive operation.
 *
 * The overlay is deliberately distinct from the visual automation overlay
 * (see {@link ./automationOverlay.ts}): that one is purely decorative
 * (pointerEvents: 'none'), whereas this one actively intercepts input
 * (pointerEvents: 'auto').
 *
 * Because the overlay would also intercept the automated actions issued by
 * chrome-devtools-mcp, it is temporarily "suspended" (pointer events disabled)
 * around each interactive tool call and "resumed" afterwards. See
 * {@link buildSuspendScript} / {@link buildResumeScript}.
 *
 * The script strings are passed to chrome-devtools-mcp's evaluate_script tool
 * which expects a plain function expression (NOT an IIFE).
 */

import type { BrowserManager } from './browserManager.js';
import { debugLogger } from '../../utils/debugLogger.js';

const INPUT_BLOCKER_ELEMENT_ID = '__gemini_input_blocker';

/**
 * Builds the JavaScript function string that injects the input-blocking
 * overlay.
 *
 * Returns a plain arrow-function expression (no trailing invocation) because
 * chrome-devtools-mcp's evaluate_script tool invokes it internally.
 */
function buildInjectionScript(): string {
  return `() => {
    const id = '${INPUT_BLOCKER_ELEMENT_ID}';
    const existing = document.getElementById(id);
    if (existing) existing.remove();

    const blocker = document.createElement('div');
    blocker.id = id;
    blocker.setAttribute('aria-hidden', 'true');
    blocker.setAttribute('role', 'presentation');
    blocker.textContent = 'Gemini CLI is controlling this browser';

    Object.assign(blocker.style, {
      position: 'fixed',
      top: '0',
      left: '0',
      right: '0',
      bottom: '0',
      zIndex: '2147483647',
      pointerEvents: 'auto',
      cursor: 'not-allowed',
      display: 'flex',
      alignItems: 'flex-start',
      justifyContent: 'center',
      paddingTop: '12px',
      fontFamily: 'sans-serif',
      fontSize: '13px',
      color: 'rgba(255,255,255,0.95)',
      background: 'transparent',
    });

    document.documentElement.appendChild(blocker);

    return 'input-blocker-injected';
  }`;
}

/**
 * Builds the JavaScript function string that removes the input-blocking
 * overlay.
 */
function buildRemovalScript(): string {
  return `() => {
    const el = document.getElementById('${INPUT_BLOCKER_ELEMENT_ID}');
    if (el) el.remove();
    return 'input-blocker-removed';
  }`;
}

/**
 * Builds the JavaScript function string that suspends the input blocker by
 * disabling its pointer events, allowing an automated action to reach the
 * underlying page.
 */
export function buildSuspendScript(): string {
  return `() => {
    const el = document.getElementById('${INPUT_BLOCKER_ELEMENT_ID}');
    if (el) el.style.pointerEvents = 'none';
    return 'input-blocker-suspended';
  }`;
}

/**
 * Builds the JavaScript function string that resumes the input blocker by
 * re-enabling its pointer events after an automated action completes.
 */
export function buildResumeScript(): string {
  return `() => {
    const el = document.getElementById('${INPUT_BLOCKER_ELEMENT_ID}');
    if (el) el.style.pointerEvents = 'auto';
    return 'input-blocker-resumed';
  }`;
}

/**
 * Injects the input-blocking overlay into the current page.
 *
 * Any error from the underlying tool call is swallowed and the promise
 * resolves with `undefined` — blocking user input is best-effort and must
 * never break the automation flow.
 */
export async function injectInputBlocker(
  browserManager: BrowserManager,
  signal?: AbortSignal,
): Promise<void> {
  try {
    debugLogger.log('Injecting input blocker...');

    const result = await browserManager.callTool(
      'evaluate_script',
      { function: buildInjectionScript() },
      signal,
    );

    if (result.isError) {
      debugLogger.warn('Failed to inject input blocker:', result);
    } else {
      debugLogger.log('Input blocker injected successfully');
    }
  } catch (error) {
    debugLogger.warn('Error injecting input blocker:', error);
    return undefined;
  }
}

/**
 * Removes the input-blocking overlay from the current page.
 *
 * Any error from the underlying tool call is swallowed and the promise
 * resolves with `undefined`.
 */
export async function removeInputBlocker(
  browserManager: BrowserManager,
  signal?: AbortSignal,
): Promise<void> {
  try {
    debugLogger.log('Removing input blocker...');

    const result = await browserManager.callTool(
      'evaluate_script',
      { function: buildRemovalScript() },
      signal,
    );

    if (result.isError) {
      debugLogger.warn('Failed to remove input blocker:', result);
    } else {
      debugLogger.log('Input blocker removed successfully');
    }
  } catch (error) {
    debugLogger.warn('Error removing input blocker:', error);
    return undefined;
  }
}
